WITH with_windows AS (SELECT *, LAG(discount, 1) OVER (PARTITION BY status, channel ORDER BY amount ASC, id ASC) AS prev_discount, CORR(shipping_fee, amount) OVER (PARTITION BY channel, customer_id) AS corr_shipping_fee_amount FROM orders) SELECT customer_id, CASE WHEN prev_discount >= 0.31 THEN 'HIGH' ELSE 'LOW' END AS prev_discount_tier, store_id, STDDEV_SAMP(shipping_fee) AS shipping_fee_stddev, STDDEV_SAMP(amount) AS amount_stddev, COUNT_IF(channel = 'store') AS store_events, SUM(CASE WHEN status = 'RETURNED' THEN amount ELSE 0 END) AS returned_amount, AVG(amount) AS avg_amount, MAX(corr_shipping_fee_amount) FILTER (WHERE status = 'CANCELLED') AS cancelled_max_corr_shipping_fee_amount, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY STDDEV_SAMP(shipping_fee) DESC) AS shipping_fee_stddev_dense_rank FROM with_windows GROUP BY customer_id, CASE WHEN prev_discount >= 0.31 THEN 'HIGH' ELSE 'LOW' END, store_id;
